<script setup lang="ts">
import {ref,watch} from 'vue'
import {useStudio} from './studioContext'
const props=defineProps<{storyboardId:string}>(),emit=defineEmits(['selected']),s=useStudio()
const rows=ref<any[]>([]),prompt=ref(''),first=ref(''),last=ref(''),busy=ref(false),error=ref(''),mode=ref('first')
const base=()=>`/projects/${s.p.value.id}/storyboards/${props.storyboardId}`
watch(()=>props.storyboardId,async()=>{rows.value=[];first.value='';last.value='';error.value='';const shot=s.rec('storyboard',props.storyboardId)?.draft;const clue=shot?s.rec('clue',shot.clueId)?.draft:null;prompt.value='生成一张古画风格的剧情预览图。只画当前情节，人物外貌和衣冠保持中国古代绘画风格，按剧情重新安排构图。无文字、无字幕。\n情节：'+(clue?.summary||clue?.name||'')+'\n画面时刻：'+(shot?.startFrame||'请填写本镜起始或结束画面')+'\n出场人物和禁止出现的内容：请在生成前补充核对。';try{rows.value=await s.api(base()+'/frames')}catch(e:any){error.value=e.message}},{immediate:true})
async function generate(){if(busy.value)return;busy.value=true;error.value='';try{await s.saveAll();const row=await s.api(base()+'/frames','POST',{prompt:prompt.value});rows.value.unshift(row)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function apply(){busy.value=true;error.value='';try{await s.saveAll();await s.legacy(await s.api(base()+'/frames-selection','PUT',{first:first.value,last:mode.value==='both'?last.value:''}));emit('selected')}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="story-frames"><h3>剧情预览图</h3><p>生成时自动附上原画与本镜选中人物截图参考板，先检查画面，再选择用于视频的首帧和尾帧。图片生成会调用阿里百炼，费用以平台账单为准。</p><label>预览图描述<textarea rows="5" v-model="prompt" :disabled="busy"/></label><button @click="generate" :disabled="busy||!prompt.trim()">{{busy?'正在处理，请稍候…':'生成剧情预览图 · qwen-image-3.0'}}</button><p v-if="error" role="alert">{{error}}</p><div class="frame-grid"><article v-for="row in rows" :key="row.id"><img :src="row.url" alt="剧情预览图"/><details><summary>本图生成描述</summary><p v-if="row.referenceNames">已提交原画及人物截图：{{row.referenceNames.join('、')}}</p><p v-else>历史预览图未记录图片参考</p><p>{{row.prompt}}</p></details></article></div><div v-if="rows.length" class="frame-controls"><label>使用方式<select v-model="mode"><option value="first">仅首帧</option><option value="both">首帧＋尾帧</option></select></label><label>首帧<select v-model="first"><option value="">请选择</option><option v-for="(row,i) in rows" :value="row.id">预览图 {{i+1}}</option></select></label><label v-if="mode==='both'">尾帧<select v-model="last"><option value="">请选择</option><option v-for="(row,i) in rows" :value="row.id">预览图 {{i+1}}</option></select></label><button @click="apply" :disabled="busy||!first||(mode==='both'&&!last)">确认用于视频</button></div></section></template>
<style scoped>.story-frames{padding:20px;margin:20px 0;background:#f0f5eb;border:1px solid #cedcc6;border-radius:12px}.story-frames p{font-size:13px;line-height:1.7}.story-frames textarea{width:100%;box-sizing:border-box}.frame-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px;margin:16px 0}.frame-grid img{width:100%;max-height:300px;object-fit:contain}.frame-controls{display:flex;gap:16px;flex-wrap:wrap;align-items:end}</style>
